window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-573e7fefa8b97ecd"]={"versions": [{"id": "FIG-573e7fefa8b97ecd", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des synchronen Aufrufmusters zur zyklischen oder bedarfsweisen Auffrischung der Pin-Richtung (<code>Port_RefreshPortDirection()</code>).\n</li><li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL). Das Modul <code>Port</code> abstrahiert die hardwarenahe Pin- und Port-Register-Konfiguration des Mikrocontrollers gegenüber höherliegenden BSW-Modulen und Applikationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>User</code>:</strong> Aufrufende Entität oberhalb des MCAL (typischerweise BSW-Manager wie EcuM, Schwellwert-/Sicherheits-Tasks oder Watchdog-/Health-Monitoring-Routinen).\n</li><li><strong><code>«module» Port</code>:</strong> BSW-Treiber-Komponente (MCAL-Modul <code>Port</code>, Stereotyp <code>«module»</code>).\n</li><li><strong>Schnittstellen &amp; Operationen:</strong>\n<ul class=\"fig-list\"><li>API: <code>void Port_RefreshPortDirection(void)</code>\n</li><li>Parameter: <code>void</code>\n</li><li>Rückgabewert: <code>void</code>\n</li><li>Assoziierte Notiz: <em>„The Port pin direction is refreshed.“</em>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger / Aufruf:</strong> Der <code>User</code> stößt synchron den Aufruf <code>Port_RefreshPortDirection()</code> an.\n</li><li><strong>Interne Treiberverarbeitung:</strong> \n<ul class=\"fig-list\"><li>Prüfung des Initialisierungsstatus (Treiber muss über <code>Port_Init()</code> initialisiert sein; andernfalls Default-Fehler <code>PORT_E_UNINIT</code> via DET, sofern <code>PORT_DEV_ERROR_DETECT == STD_ON</code>).\n</li><li>Hardware-Schreibzugriff: Der Treiber durchläuft alle Ports/Pins und schreibt das Richtungsregister (Input/Output) für alle Pins neu, deren Konfiguration zur Laufzeit unveränderlich ist (<code>PortPinDirectionChangeable == FALSE</code>).\n</li><li>Pins mit <code>PortPinDirectionChangeable == TRUE</code> werden explizit <strong>nicht</strong> überschrieben, um dynamisch geänderte Pin-Zustände nicht zu korrumpieren.\n</li></ul>\n</li><li><strong>Abschluss &amp; Rückkehr:</strong> Synchroner Return (<code>void</code>) an den Aufrufer nach Abschluss der Registeraktualisierungen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Anforderungen (AUTOSAR SWS Port Driver):</strong>\n<ul class=\"fig-list\"><li><strong>SWS_Port_00060:</strong> Auffrischung ausschließlich für Pins mit <code>PortPinDirectionChangeable == FALSE</code>.\n</li><li><strong>SWS_Port_00061:</strong> Ausschluss von Pins mit dynamischer Richtungsänderung (<code>PortPinDirectionChangeable == TRUE</code>).\n</li><li><strong>SWS_Port_00066 / SWS_Port_00077:</strong> Die Service-Funktion ist <strong>synchron</strong> und <strong>nicht reentrant</strong> (<code>Non Reentrant</code>).\n</li></ul>\n</li><li><strong>Safety &amp; Robustness (EMV / Soft-Errors):</strong>\n<ul class=\"fig-list\"><li>Dient primär der Erfüllung von ASIL-/Funktionaler-Sicherheits-Anforderungen (z. B. nach ISO 26262), um Registerverfälschungen (Bitflips, EMV-Transienten) zyklisch zu heilen.\n</li></ul>\n</li><li><strong>Konfigurations- und Integrationsaspekte:</strong>\n<ul class=\"fig-list\"><li>Schalter <code>PORT_SET_PIN_DIRECTION_API</code>: Muss nicht zwingend aktiviert sein, damit <code>Port_RefreshPortDirection()</code> verfügbar ist (abhängig von der Treiberkonfiguration).\n</li><li>Aufrufkontext: Darf wegen <code>Non Reentrant</code> nicht nebenläufig aus Interrupt-Kontexten (ISRs) oder ungeschützten preemptiven Tasks aufgerufen werden; typische Platzierung erfolgt in einer periodischen Low-Priority-/Sicherheits-Task.\n</li></ul>\n</li></ul>"}, {"id": "FIG-c2fac5ce101c827a", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des synchronen Aufrufmusters zur zyklischen oder bedarfsweisen Auffrischung der Pin-Richtung (<code>Port_RefreshPortDirection()</code>).\n</li><li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic Platform, Microcontroller Abstraction Layer (MCAL). Das Modul <code>Port</code> abstrahiert die hardwarenahe Pin- und Port-Register-Konfiguration des Mikrocontrollers gegenüber höherliegenden BSW-Modulen und Applikationen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>User</code>:</strong> Aufrufende Entität oberhalb des MCAL (typischerweise BSW-Manager wie EcuM, Schwellwert-/Sicherheits-Tasks oder Watchdog-/Health-Monitoring-Routinen).\n</li><li><strong><code>«module» Port</code>:</strong> BSW-Treiber-Komponente (MCAL-Modul <code>Port</code>, Stereotyp <code>«module»</code>).\n</li><li><strong>Schnittstellen &amp; Operationen:</strong>\n<ul class=\"fig-list\"><li>API: <code>void Port_RefreshPortDirection(void)</code>\n</li><li>Parameter: <code>void</code>\n</li><li>Rückgabewert: <code>void</code>\n</li><li>Assoziierte Notiz: <em>„The Port pin direction is refreshed.“</em>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger / Aufruf:</strong> Der <code>User</code> stößt synchron den Aufruf <code>Port_RefreshPortDirection()</code> an.\n</li><li><strong>Interne Treiberverarbeitung:</strong> \n<ul class=\"fig-list\"><li>Prüfung des Initialisierungsstatus (Treiber muss über <code>Port_Init()</code> initialisiert sein; andernfalls Default-Fehler <code>PORT_E_UNINIT</code> via DET, sofern <code>PORT_DEV_ERROR_DETECT == STD_ON</code>).\n</li><li>Hardware-Schreibzugriff: Der Treiber durchläuft alle Ports/Pins und schreibt das Richtungsregister (Input/Output) für alle Pins neu, deren Konfiguration zur Laufzeit unveränderlich ist (<code>PortPinDirectionChangeable == FALSE</code>).\n</li><li>Pins mit <code>PortPinDirectionChangeable == TRUE</code> werden explizit <strong>nicht</strong> überschrieben, um dynamisch geänderte Pin-Zustände nicht zu korrumpieren.\n</li></ul>\n</li><li><strong>Abschluss &amp; Rückkehr:</strong> Synchroner Return (<code>void</code>) an den Aufrufer nach Abschluss der Registeraktualisierungen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Anforderungen (AUTOSAR SWS Port Driver):</strong>\n<ul class=\"fig-list\"><li><strong>SWS_Port_00060:</strong> Auffrischung ausschließlich für Pins mit <code>PortPinDirectionChangeable == FALSE</code>.\n</li><li><strong>SWS_Port_00061:</strong> Ausschluss von Pins mit dynamischer Richtungsänderung (<code>PortPinDirectionChangeable == TRUE</code>).\n</li><li><strong>SWS_Port_00066 / SWS_Port_00077:</strong> Die Service-Funktion ist <strong>synchron</strong> und <strong>nicht reentrant</strong> (<code>Non Reentrant</code>).\n</li></ul>\n</li><li><strong>Safety &amp; Robustness (EMV / Soft-Errors):</strong>\n<ul class=\"fig-list\"><li>Dient primär der Erfüllung von ASIL-/Funktionaler-Sicherheits-Anforderungen (z. B. nach ISO 26262), um Registerverfälschungen (Bitflips, EMV-Transienten) zyklisch zu heilen.\n</li></ul>\n</li><li><strong>Konfigurations- und Integrationsaspekte:</strong>\n<ul class=\"fig-list\"><li>Schalter <code>PORT_SET_PIN_DIRECTION_API</code>: Muss nicht zwingend aktiviert sein, damit <code>Port_RefreshPortDirection()</code> verfügbar ist (abhängig von der Treiberkonfiguration).\n</li><li>Aufrufkontext: Darf wegen <code>Non Reentrant</code> nicht nebenläufig aus Interrupt-Kontexten (ISRs) oder ungeschützten preemptiven Tasks aufgerufen werden; typische Platzierung erfolgt in einer periodischen Low-Priority-/Sicherheits-Task.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-573e7fefa8b97ecd", "to": "FIG-c2fac5ce101c827a", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
